{
  "summary": "synthetic-provider 的 credit-apply 接口当前 QPS 已达契约上限的 90%，并存在 2% 超时率，且已有确认因上游超时导致的历史故障。综合评估容量饱和、超时劣化及故障复发风险，建议进入人工治理；本次仅提供只读治理建议，不执行任何配置修改。",
  "riskLevel": "HIGH",
  "findings": [
    {
      "ruleId": "R001",
      "matched": true,
      "evidence": "接口契约 qpsLimit=20，当前运行指标 qps=18，容量使用率约 90%。",
      "recommendation": "设置容量预警阈值并制定扩容计划；当流量达到上限 80% 时触发人工评估，避免突发流量引发拥塞或限流。",
      "requiresHumanReview": true
    },
    {
      "ruleId": "R002",
      "matched": true,
      "evidence": "运行指标 timeoutRate=0.02，即当前 2% 请求出现超时；平均延迟 420ms 虽低于契约 timeoutMs=3000，但失败率仍然偏高。",
      "recommendation": "对超时样本进行全链路追踪，定位上游超时点与重试链；设置上游分级超时和快速失败策略，降低全局等待时间。",
      "requiresHumanReview": true
    },
    {
      "ruleId": "R003",
      "matched": true,
      "evidence": "历史故障 incident-001 状态为 confirmed、cause 为 upstream-timeout；当前接口仍接近容量上限并持续出现超时，同类故障具备复发条件。",
      "recommendation": "人工审查 incident-001 的缓解措施是否全面落地，并开展上游依赖故障演练，验证熔断、降级和隔离机制可防止同类超时扩散。",
      "requiresHumanReview": true
    },
    {
      "ruleId": "R004",
      "matched": true,
      "evidence": "运行指标 activeThreads=6、maxThreads=10；在 QPS 18 且 avgLatencyMs=420 的情况下，并发占用已接近可用线程池的较高水位，叠加上游慢调用时线程池可能被快速耗尽。",
      "recommendation": "人工评估线程池隔离和慢调用隔离策略，对关键上游依赖配置独立熔断器或信号量，避免局部超时拖垮 credit-apply 接口。",
      "requiresHumanReview": true
    }
  ],
  "requiresHumanReview": true
}
